'use strict';
self.onmessage=async({data})=>{let image;try{const response=await fetch(data.picture);image=await createImageBitmap(await response.blob());const result={ok:true,width:image.width,height:image.height};if(data.thumbnail){const scale=Math.min(1,512/image.width,512/image.height),canvas=new OffscreenCanvas(Math.max(1,Math.round(image.width*scale)),Math.max(1,Math.round(image.height*scale)));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const mime=data.picture.startsWith('data:image/jpeg;')?'image/jpeg':'image/png',blob=await canvas.convertToBlob({type:mime,quality:0.85});if(blob.size>2*1024*1024)throw Error('Thumbnail too large');result.thumbnail={mime,bytes:new Uint8Array(await blob.arrayBuffer()),width:canvas.width,height:canvas.height};}self.postMessage({id:data.id,result});}catch{self.postMessage({id:data.id,result:{ok:false}});}finally{image?.close();}};
